'use client'

import { useState } from 'react'
import styles from './handbook.module.css'

const KEYWORDS = 'async|await|def|return|import|from|for|in|with|as|if|elif|else|try|except|finally|raise|class|None|True|False|lambda|yield|const|let|var|function|SELECT|FROM|WHERE|JOIN|INSERT|UPDATE|DELETE|CREATE|TABLE'
// One pass over the raw line, so a later rule never rewrites markup an earlier one added.
const TOKEN = new RegExp(`((?:^|(?<=\\s))(?:#|--|//).*$)|("(?:[^"\\\\]|\\\\.)*"|'(?:[^'\\\\]|\\\\.)*')|\\b(${KEYWORDS})\\b|\\b(\\d+(?:\\.\\d+)?)\\b`, 'g')
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

/** A light highlighter: comments, strings, keywords and numbers. Each piece is escaped as it is wrapped. */
export function highlight(line: string): string {
  let out = ''
  let last = 0
  for (const m of line.matchAll(TOKEN)) {
    const cls = m[1] ? styles.tc : m[2] ? styles.ts : m[3] ? styles.tk : styles.tn
    out += esc(line.slice(last, m.index)) + `<span class="${cls}">${esc(m[0])}</span>`
    last = m.index! + m[0].length
  }
  return out + esc(line.slice(last))
}

export function CodeBlock({ lang, lines, note, result }: { lang: string; lines: string[]; note?: string; result?: { headers: string[]; rows: string[][] } }) {
  const [copied, setCopied] = useState(false)
  const copy = () => navigator.clipboard?.writeText(lines.join('\n')).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1200) }, () => undefined)
  return (
    <div className={styles.blk}>
      <div className={styles.code}>
        <span className={styles.lang}>{lang}</span>
        <button type="button" className={styles.copy} onClick={copy}>{copied ? 'Copied' : 'Copy'}</button>
        <pre dangerouslySetInnerHTML={{ __html: lines.map(highlight).join('\n') }} />
      </div>
      {result && (
        <table className={styles.table}><thead><tr>{result.headers.map((x) => <th key={x}>{x}</th>)}</tr></thead><tbody>{result.rows.map((r, i) => <tr key={i}>{r.map((c, j) => <td key={j}>{c}</td>)}</tr>)}</tbody></table>
      )}
      {note && <p className={styles.cnote}>{note}</p>}
    </div>
  )
}
